static gboolean honk_accessibility_poll(gpointer data) {
    native_sdk_gtk_native_view_t *view = data;
    if (!view || !view->honk_accessibility || !view->window || !view->label) return G_SOURCE_REMOVE;
    honk_accessibility_bounds(view);
    HonkAccessibilityAction action = {0};
    if (honk_a11y_poll(view->honk_accessibility, &action)) {
        // Runtime callbacks may close the view. Do not access it after dispatch.
        native_sdk_emit(view->window->host, (native_sdk_gtk_event_t){
            .kind = (native_sdk_gtk_event_kind_t)18,
            .window_id = view->window->id,
            .view_label = view->label,
            .view_label_len = strlen(view->label),
            .frame_index = action.id,
            .input_kind = action.action,
            .input_text = (const char *)action.text,
            .input_text_len = action.text_len,
        });
    }
    return G_SOURCE_CONTINUE;
}

